//! Scoring the hand-authored corpus against the pass — and the honest half of that sentence.
//!
//! The corpus is *hand-authored* against [ADR-007 §4](../../../docs/adr/0007-complexity.md), which is
//! the only way a corpus can check anything: a `truth.json` generated by running the pass would prove
//! that the pass agrees with itself, which is worth nothing at all. So the figures here were written
//! by a reader counting the constructs in each file the way the ADR says to count them, and a
//! disagreement is an event to adjudicate, not to bless.
//!
//! The bar this module enforces is ADR-007 §11.2's, quoted through §14: **every definition the
//! extractor can see is scored at 100 %, and every miss is a blind spot the ADR already named.** The
//! second half is the one with a mechanism: a figure may differ from the truth only on a scope carrying
//! a `synthetic::*` mark — a macro, a decorator, a computed method name, a synthesised accessor, a
//! build constraint — because those are the scopes `s1` measured as irreducible and §7.3 decided are
//! floors rather than failures. A miss with no mark behind it is a bug, and it is red.

use super::Measured;
use serde_json::Value;
use std::collections::BTreeMap;
use std::path::Path;

/// One expected figure, as hand-authored.
#[derive(Debug, Clone)]
pub(crate) struct Expect {
    /// The dotted name the extractor gives the unit.
    pub name: String,
    /// `fn` or `method`.
    pub kind: String,
    /// The expected `V(G)`; `None` means the unit is expected to be unknown.
    pub figure: Option<usize>,
    /// The expected reason code when the figure is unknown (`""` when it is measured).
    pub reason: String,
    /// How many decision points the ADR's list earns here — a figure minus its base, checked
    /// separately so an off-by-one in the base cannot hide behind a matching total.
    pub points: Option<usize>,
}

/// What `truth.json` says about one file.
#[derive(Debug, Clone, Default)]
pub(crate) struct FileTruth {
    pub functions: Vec<Expect>,
    /// Optional expectations, checked when present. A JSON `null` here means *expected to be
    /// absent* — `sum` of an unreadable file is not "unknown to the truth", it is `?`, and the truth
    /// says so. A missing key is the one that means "the truth does not constrain this".
    pub state: Option<String>,
    pub sum: Option<Option<i64>>,
    pub max: Option<Option<i64>>,
    pub reason: Option<String>,
    pub marks: Vec<String>,
}

/// One language's corpus truth.
#[derive(Debug, Clone)]
pub(crate) struct Truth {
    pub language: String,
    pub basis: String,
    pub notes: String,
    pub files: BTreeMap<String, FileTruth>,
}

impl Truth {
    pub(crate) fn load(dir: &Path, language: &str) -> Result<Truth, String> {
        let path = dir.join("truth.json");
        let text = std::fs::read_to_string(&path)
            .map_err(|e| format!("{}: {e} — the corpus ships its own truth", path.display()))?;
        let value: Value =
            serde_json::from_str(&text).map_err(|e| format!("{}: {e}", path.display()))?;
        let got = value["language"].as_str().unwrap_or("");
        if got != language {
            return Err(format!(
                "{}: says `{got}`, the harness is reading it as `{language}`",
                path.display()
            ));
        }
        let basis = value["basis"].as_str().unwrap_or("").to_string();
        if basis != fathom_analyze::structure::complexity::BASIS {
            return Err(format!(
                "{}: authored against basis `{basis}`, this build counts `{}` — a figure of one \
                 basis is not comparable with a figure of another (ADR-007 §9.5), so the corpus and \
                 the code have to be changed together",
                path.display(),
                fathom_analyze::structure::complexity::BASIS
            ));
        }
        let mut files = BTreeMap::new();
        let entries = value["files"]
            .as_object()
            .ok_or_else(|| format!("{}: no `files` object", path.display()))?;
        for (path, row) in entries {
            let nullable = |key: &str| -> Option<Option<i64>> {
                match row.get(key) {
                    None => None,
                    Some(Value::Null) => Some(None),
                    Some(value) => Some(value.as_i64()),
                }
            };
            let mut file = FileTruth {
                state: row["state"].as_str().map(str::to_string),
                sum: nullable("sum"),
                max: nullable("max"),
                reason: row["reason"].as_str().map(str::to_string),
                marks: row["marks"]
                    .as_array()
                    .map(|list| {
                        list.iter()
                            .filter_map(Value::as_str)
                            .map(str::to_string)
                            .collect()
                    })
                    .unwrap_or_default(),
                ..Default::default()
            };
            for expect in row["functions"].as_array().into_iter().flatten() {
                file.functions.push(Expect {
                    name: expect["n"].as_str().unwrap_or("").to_string(),
                    kind: expect["kind"].as_str().unwrap_or("").to_string(),
                    figure: expect["v"].as_u64().map(|v| v as usize),
                    reason: expect["r"].as_str().unwrap_or("").to_string(),
                    points: expect["points"].as_u64().map(|v| v as usize),
                });
            }
            files.insert(path.clone(), file);
        }
        Ok(Truth {
            language: language.to_string(),
            basis,
            notes: value["notes"].as_str().unwrap_or("").to_string(),
            files,
        })
    }
}

/// The score of one language's corpus.
#[derive(Default)]
pub(crate) struct Score {
    /// Figures the truth names.
    pub expected: usize,
    /// Figures met exactly.
    pub matched: usize,
    /// Misses with nothing behind them: bugs, and red.
    pub misses: Vec<String>,
    /// Misses inside a scope ADR-007 §7.3 already named. Reported, not excused quietly.
    pub blind_spot_misses: Vec<String>,
    /// Units with no figure and no reason code — the shape ADR-007 §7 refuses to represent.
    pub units_without_reason: Vec<String>,
    /// Whether every unit and file satisfies "unknown is never `0`".
    pub unknown_never_zero: bool,
    /// Corpus functions the truth does not name, and truth functions the run did not produce.
    pub unlisted: Vec<String>,
}

impl Score {
    pub(crate) fn row(&self) -> Value {
        serde_json::json!({
            "expected": self.expected,
            "matched": self.matched,
            "score": if self.expected == 0 { 0.0 } else { self.matched as f64 / self.expected as f64 },
            "misses": self.misses,
            "blind_spot_misses": self.blind_spot_misses,
            "unlisted": self.unlisted,
            "truth_files": self.expected,
            "definitions_the_extractor_can_see": self.expected - self.blind_spot_misses.len(),
            "bar": "100 % of the definitions the extractor can see; a miss must be a scope ADR-007 \
                    §7.3 marks, named",
        })
    }
}

/// Compare one language's corpus with its truth.
pub(crate) fn score(truth: &Truth, files: &[Measured]) -> Score {
    let mut out = Score {
        unknown_never_zero: true,
        ..Default::default()
    };
    let measured: BTreeMap<&str, &Measured> = files
        .iter()
        .map(|file| (file.path.as_str(), file))
        .collect();

    for (path, file_truth) in &truth.files {
        let Some(file) = measured.get(path.as_str()) else {
            out.misses.push(format!(
                "{path}: named in truth.json, not in the corpus directory"
            ));
            continue;
        };
        let mark = |name: &str| -> bool {
            let unit_mark = file
                .report
                .units
                .iter()
                .find(|unit| unit.name == name)
                .is_some_and(|unit| !unit.marks.is_empty());
            unit_mark || !file.report.marks.is_empty()
        };
        check_optional(path, file, file_truth, &mut out);

        // Name is not always unique — two overload signatures and their implementation share one name,
        // and `attr_accessor :x` names a getter and a setter over one node — so expectations consume
        // the units of their name in source order. Position, not name, decides which `overlapped` an
        // expectation is about, which is the same order the dump prints.
        let mut pool: BTreeMap<&str, std::collections::VecDeque<&_>> = BTreeMap::new();
        for unit in &file.report.units {
            pool.entry(unit.name.as_str()).or_default().push_back(unit);
        }
        let mut named: Vec<String> = Vec::new();
        for expect in &file_truth.functions {
            named.push(expect.name.clone());
            out.expected += 1;
            let unit = pool
                .get_mut(expect.name.as_str())
                .and_then(std::collections::VecDeque::pop_front);
            let Some(unit) = unit else {
                out.misses.push(format!(
                    "{path}: `{}` is a unit in the truth and not one the pass found",
                    expect.name
                ));
                continue;
            };
            let figure_matches = unit.figure == expect.figure;
            let reason = unit.reason.as_ref().map(|r| r.as_str()).unwrap_or("");
            let reason_matches = reason == expect.reason;
            let kind_matches = expect.kind.is_empty() || expect.kind == unit.kind;
            let points_matches = expect
                .points
                .is_none_or(|points| points == unit.points.len());
            if figure_matches && reason_matches && kind_matches && points_matches {
                out.matched += 1;
                continue;
            }
            let sentence = format!(
                "{path}: `{}` expected {} [{}] got {} [{}] ({} points expected, {} counted)",
                expect.name,
                expect
                    .figure
                    .map_or_else(|| "?".to_string(), |v| v.to_string()),
                if expect.reason.is_empty() {
                    "measured".to_string()
                } else {
                    expect.reason.clone()
                },
                unit.figure
                    .map_or_else(|| "?".to_string(), |v| v.to_string()),
                reason,
                expect.points.unwrap_or(0),
                unit.points.len()
            );
            // The only excuse a miss may have, and it is a named one.
            if mark(&expect.name) {
                out.blind_spot_misses
                    .push(format!("{sentence} — in a marked scope"));
            } else {
                out.misses.push(sentence);
            }
        }
        for unit in &file.report.units {
            if !named.iter().any(|name| name == &unit.name) {
                out.unlisted.push(format!(
                    "{path}: `{}` was counted and the truth does not name it",
                    unit.name
                ));
            }
            if unit.figure.is_none() && unit.reason.is_none() {
                out.units_without_reason
                    .push(format!("{path}:{}", unit.name));
            }
            if unit.figure == Some(0) {
                out.unknown_never_zero = false;
                out.misses.push(format!(
                    "{path}:{}: a unit's figure is 0, which is never a unit's figure",
                    unit.name
                ));
            }
        }
        // ADR-007 §7.1, at file level: a `?` must say why, and a printed `0` may only ever be a
        // fact about the file (`no_bodies`, `absent_revision`). A refusal such as `parse_failed` or
        // `language_unknown` is a legitimate `?` and the two empty-file cases in the corpus are both
        // refusals — the rule is about the *figure*, not about which reason was brave enough to show.
        let every_unit_speaks = !file.report.units.is_empty()
            && file.report.units.iter().all(|unit| unit.reason.is_some());
        if file.report.sum.is_none() && file.report.reason.is_none() && !every_unit_speaks {
            out.unknown_never_zero = false;
            out.misses.push(format!(
                "{path}: no figure and no reason code, which prints a bare `?`"
            ));
        }
        if let Some(0) = file.report.sum {
            let measured = file
                .report
                .reason
                .as_ref()
                .is_some_and(|reason| reason.is_measured_zero());
            if !measured {
                out.unknown_never_zero = false;
                out.misses.push(format!(
                    "{path}: a file figure of 0 that is not `absent_revision` or `no_bodies`"
                ));
            }
        }
    }
    for file in files {
        if !truth.files.contains_key(&file.path) {
            out.unlisted.push(format!(
                "{}: in the corpus and not named in truth.json",
                file.path
            ));
        }
    }
    out
}

/// The optional per-file expectations: state, roll-ups, file reason and marks.
fn check_optional(path: &str, file: &Measured, file_truth: &FileTruth, out: &mut Score) {
    if let Some(state) = &file_truth.state
        && state != file.report.state().as_str()
    {
        out.misses.push(format!(
            "{path}: state expected `{state}`, counted `{}`",
            file.report.state().as_str()
        ));
    }
    for (label, expected, counted) in [
        (
            "sum",
            file_truth.sum,
            file.report.sum.map(i64::try_from).and_then(Result::ok),
        ),
        (
            "max",
            file_truth.max,
            file.report.max.map(i64::try_from).and_then(Result::ok),
        ),
    ] {
        // A counted `None` is not "unconstrained": the pass knows the file has no figure, and the
        // truth is allowed to say so. Only an *absent* key in truth.json leaves the choice open.
        if Some(counted) != expected {
            out.misses.push(format!(
                "{path}: {label} expected {:?}, counted {:?}",
                expected, counted
            ));
        }
    }
    if let Some(reason) = &file_truth.reason {
        let got = file.report.reason.as_ref().map_or("", |r| r.as_str());
        if got != reason {
            out.misses.push(format!(
                "{path}: reason expected `{reason}`, counted `{got}`"
            ));
        }
    }
    if !file_truth.marks.is_empty() && file.report.marks != file_truth.marks {
        out.misses.push(format!(
            "{path}: marks expected {:?}, counted {:?}",
            file_truth.marks, file.report.marks
        ));
    }
}
